SetFunctionName("void SetComponent(int i, float value)");
Quaternion v0( 1.0f, 2.0f, 3.0f, 4.0f );
v0.SetComponent( 0, 101.0f );
Quaternion v1( 101.0f, 2.0f, 3.0f, 4.0f );
v1.SetComponent( 1, 10.0f );
Quaternion v2( 101.0f, 10.0f, 3.0f, 4.0f );
v2.SetComponent( 2, 69.0f );
Quaternion v3( 101.0f, 10.0f, 69.0f, 4.0f );
v3.SetComponent( 3, 9.0f );
Validate(
    (float)v0.X() == 101.0f && (float)v0.Y() == 2.0f && (float)v0.Z() == 3.0f && (float)v0.W() == 4.0f &&
    (float)v1.X() == 101.0f && (float)v1.Y() == 10.0f && (float)v1.Z() == 3.0f && (float)v1.W() == 4.0f &&
    (float)v2.X() == 101.0f && (float)v2.Y() == 10.0f && (float)v2.Z() == 69.0f && (float)v2.W() == 4.0f &&
    (float)v3.X() == 101.0f && (float)v3.Y() == 10.0f && (float)v3.Z() == 69.0f && (float)v3.W() == 9.0f
);



