Quaternion qA, qB, qC, qOut1, qOut2;
qA.Set(1.0f, 2.0f, 3.45f, 2.1f);
qB.Set(-3.0f, 1.0f, 5.3f, 2.1f);
qC.Set(1.0f, -1.0f, -2.3f, -0.1f);

SetFunctionName("NLerpEstimate( const Quaternion &v0, const Quaternion &v1, float_test_type t)");
qOut1= NLerpEstimate(qA, qB, (float_test_type)0.15f);
qOut2= NLerpEstimate(qB, qC, (float_test_type)0.3f);
Validate(
        // This is sort of a "meta" test.  Ensure that the unit test covers both conditions in the implementation code.
        (float)Dot(qA, qB) > 0.0f &&
        (float)Dot(qB, qC) < 0.0f &&

        IsEqualWithEpsilon((float)qOut1.X(), 0.085500620f, 0.003f) &&
        IsEqualWithEpsilon((float)qOut1.Y(), 0.39544040f, 0.003f) &&
        IsEqualWithEpsilon((float)qOut1.Z(), 0.79675895f, 0.003f) &&
        IsEqualWithEpsilon((float)qOut1.W(), 0.44887829f, 0.003f) &&
        IsEqualWithEpsilon((float)qOut2.X(), -0.45059002559613476f, 0.003f) &&
        IsEqualWithEpsilon((float)qOut2.Y(),  0.18774584399838951f, 0.003f) &&
        IsEqualWithEpsilon((float)qOut2.Z(),  0.82608171359291382f, 0.003f) &&
        IsEqualWithEpsilon((float)qOut2.W(),  0.28161876599758423f, 0.003f)
        );


