qA.Set(1.0f, 2.0f, 3.45f, 2.1f);
qB.Set(-3.0f, 1.0f, 5.3f, 2.1f);
qC.Set(1.0f, -1.0f, -2.3f, -0.1f);

SetFunctionName("NLerpFast( const Quaternion &v0, const Quaternion &v1, float_test_type t)");
