#if !defined EA_PLATFORM_PS3_SPU
        SetFunctionName("IsAnyNaN(Quaternion v)");

        float zero = 0.0f;
        float_test_type nan = float_test_type(zero / zero);
        int numPermutations = 1 << Quaternion::NumberOfElement;
        bool result = true;
        for( int curPermutation=0;curPermutation<numPermutations;curPermutation++)
        {
            Quaternion q = GetQuaternion_Zero();
            for( int elem = 0; elem < Quaternion::NumberOfElement; elem++ )
            {
                if( curPermutation & (1<<elem) )
                {
                    q.SetComponent( elem, nan );
                }
            }
            if( curPermutation == 0 )
            {
                // All bits are zero so the quat has no NaN's
                result &= !IsAnyNaN(q);
            }
            else
            {
                // At least one element is NaN.
                result &= IsAnyNaN(q);
            }
        }
        Validate(result);
#endif



