);




 SetFunctionName("Quaternion Pow(Quaternion::InParam v, VecFloat::InParam e)");

 Quaternion identity_q, input_q;
 identity_q.SetIdentity();

 Vector3 xAxisPositive(1.0f, 0.0f, 0.0f);
 Vector3 xAxisNegative(-1.0f, 0.0f, 0.0f);
 float_test_type angle60( PI / 3.0f );
 input_q = QuaternionFromAxisRotationAngle(xAxisPositive, float_test_type(angle60));

 Quaternion q0 = Pow(input_q, float_test_type(0.0f));
 Quaternion q1 = Pow(input_q, float_test_type(1.0f));
 Quaternion q2 = Pow(input_q, float_test_type(2.0f));
 Quaternion q05 = Pow(input_q, float_test_type(0.5f));
 Quaternion qn0 = Pow(input_q, float_test_type(-0.0f));
 Quaternion qn1 = Pow(input_q, float_test_type(-1.0f));
 Quaternion qn2 = Pow(input_q, float_test_type(-2.0f));
 Quaternion qn05 = Pow(input_q, float_test_type(-0.5f));

 Vector3 q0_axis, q1_axis, q2_axis, q05_axis, qn0_axis, qn1_axis, qn2_axis, qn05_axis;
 float_test_type q0_angle, q1_angle, q2_angle, q05_angle, qn0_angle, qn1_angle, qn2_angle, qn05_angle;

 AxisAngleFromQuaternion(q0, q0_axis, q0_angle);
 AxisAngleFromQuaternion(q1, q1_axis, q1_angle);
 AxisAngleFromQuaternion(q2, q2_axis, q2_angle);
 AxisAngleFromQuaternion(q05, q05_axis, q05_angle);
 AxisAngleFromQuaternion(qn0, qn0_axis, qn0_angle);
 AxisAngleFromQuaternion(qn1, qn1_axis, qn1_angle);
 AxisAngleFromQuaternion(qn2, qn2_axis, qn2_angle);
 AxisAngleFromQuaternion(qn05, qn05_axis, qn05_angle);


Validate( 
 IsSimilar(q0_angle, (float_test_type)0.0f) && IsSimilar(q1_angle, angle60) &&
 IsSimilar(q2_angle, angle60 * 2.0f) && IsSimilar(q05_angle, angle60 / 2.0f) && 
 IsSimilar(qn0_angle, (float_test_type)0.0f) && IsSimilar(qn1_angle, angle60) &&
 IsSimilar(qn2_angle, angle60 * 2.0f) && IsSimilar(qn05_angle, angle60 / 2.0f) &&
 IsSimilar(q0_axis, xAxisPositive, (float_test_type)0.0001f) && IsSimilar(q1_axis, xAxisPositive, (float_test_type)0.0001f) &&
 IsSimilar(q2_axis, xAxisPositive, (float_test_type)0.0001f) && IsSimilar(q05_axis, xAxisPositive, (float_test_type)0.0001f) &&
 IsSimilar(qn0_axis, xAxisPositive, (float_test_type)0.0001f) && IsSimilar(qn1_axis, xAxisNegative, (float_test_type)0.0001f) &&
 IsSimilar(qn2_axis, xAxisNegative, (float_test_type)0.0001f) && IsSimilar(qn05_axis, xAxisNegative, (float_test_type)0.0001f)  
 );



